operations.text:
enum {
    METADATA_MEDIA_HINT = 1u,
    METADATA_NORMALIZATION_HINT = 2u,
    METADATA_TEXT_NORMALIZATION_HINT = 4u
};

/* A compact flat object needs only one container frame. Validate every string
 * and commit hints only after its closing brace; unsupported values or spacing
 * leave the ordinary parser's cursor, hints, and parent state untouched. */
static int parse_compact_metadata_object(
    const uint8_t* src, uint32_t len, uint32_t start, uint32_t requested_hints,
    uint32_t* out_end, uint32_t* out_hints
) {
    if (start >= len || src[start] != '{') { return 0; }
    uint32_t i = start + 1u;
    uint32_t hints = 0u;
    if (i < len && src[i] == '}') {
        *out_end = i + 1u;
        *out_hints = 0u;
        return 1;
    }
    for (;;) {
        if (i >= len || src[i] != '"') { return 0; }
        const uint32_t key_start = i;
        uint32_t key_end;
        if (!parse_string_span(src, len, i, &key_end)) { return 0; }
        if ((requested_hints & METADATA_MEDIA_HINT) != 0u &&
            (src[i + 1u] == 'i' || src[i + 1u] == '\\') &&
            is_media_marker_at(src, key_end, i)) {
            hints |= METADATA_MEDIA_HINT;
        }
        if (key_end >= len || src[key_end] != ':') { return 0; }
        i = key_end + 1u;
        if (i >= len || src[i] != '"') { return 0; }
        uint32_t value_end;
        if (!parse_string_span(src, len, i, &value_end)) { return 0; }
        if ((requested_hints & METADATA_MEDIA_HINT) != 0u &&
            (src[i + 1u] == 'i' || src[i + 1u] == '\\') &&
            is_media_marker_at(src, value_end, i)) {
            hints |= METADATA_MEDIA_HINT;
        }
        if ((requested_hints & METADATA_TEXT_NORMALIZATION_HINT) != 0u &&
            (src[key_start + 1u] == 't' || src[key_start + 1u] == '\\') &&
            type_text_pair_at(src, len, key_start, key_end)) {
            hints |= METADATA_NORMALIZATION_HINT | METADATA_TEXT_NORMALIZATION_HINT;
        }
        i = value_end;
        if (i >= len) { return 0; }
        if (src[i] == '}') {
            *out_end = i + 1u;
            *out_hints = hints;
            return 1;
        }
        if (src[i] != ',') { return 0; }
        ++i;
    }
}

static inline int is_metadata_key(const uint8_t* src, uint32_t start, uint32_t end) {
    const uint32_t length = end - start;
    if (length != 6u && length != 7u) { return 0; }
    uint32_t prefix;
    __builtin_memcpy(&prefix, src + start, sizeof(prefix));
    return (length == 6u && prefix == UINT32_C(0x74616422) &&
        src[start + 4u] == 'a' && src[start + 5u] == '"') ||
        (length == 7u && prefix == UINT32_C(0x79747322) &&
        src[start + 4u] == 'l' && src[start + 5u] == 'e' && src[start + 6u] == '"');
}

if (common_key_kind == COMMON_STRUCTURED_KEY_NONE &&
    (src[i + 1u] == 'd' || src[i + 1u] == 's') &&
    depth < MAX_JSON_NESTING && is_metadata_key(src, i, s_end) &&
    len - s_end > 1u && src[s_end] == ':' && src[s_end + 1u] == '{') {
    uint32_t requested_hints = 0u;
    if (media_hint != 0 && *media_hint == 0u) {
        requested_hints |= METADATA_MEDIA_HINT;
    }
    if ((normalization_hint != 0 && *normalization_hint == 0u) ||
        (text_normalization_hint != 0 && *text_normalization_hint == 0u)) {
        requested_hints |= METADATA_TEXT_NORMALIZATION_HINT;
    }
    uint32_t metadata_end;
    uint32_t hints;
    if (parse_compact_metadata_object(
            src, len, s_end + 1u, requested_hints, &metadata_end, &hints)) {
        if ((hints & METADATA_MEDIA_HINT) != 0u && media_hint != 0) { *media_hint = 1u; }
        if ((hints & METADATA_NORMALIZATION_HINT) != 0u && normalization_hint != 0) { *normalization_hint = 1u; }
        if ((hints & METADATA_TEXT_NORMALIZATION_HINT) != 0u && text_normalization_hint != 0) { *text_normalization_hint = 1u; }
        state = OBJECT_AFTER_VALUE;
        i = metadata_end;
        continue;
    }
}
